{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"tool\":\"sql_query\",\"arguments\":{\"company_name\":\"CLOSE_fin_05\",\"table_name\":\"ledger\",\"query\":\"WITH eligible AS (SELECT kind,event_key,invoice_id,vendor,business_date,recorded_at,revision,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ledger WHERE datetime(recorded_at)<=datetime('2026-10-24T12:00:00') AND business_date<='2026-10-23'), ranked AS (SELECT kind,event_key,invoice_id,vendor,business_date,revision,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den,ROW_NUMBER() OVER (PARTITION BY kind,event_key ORDER BY revision DESC) rn FROM eligible), latest AS (SELECT kind,event_key,invoice_id,vendor,business_date,status,amount_minor,currency,due_date,discount_until,terms_code,discount_bps,fx_num,fx_den FROM ranked WHERE rn=1), inv AS (SELECT event_key,amount_minor,currency,business_date,discount_until,terms_code FROM latest WHERE kind='invoice' AND status='active' AND vendor='BLUE' AND due_date<='2026-10-30'), bal AS (SELECT i.event_key,i.amount_minor gross,i.currency,i.business_date,i.discount_until,i.terms_code,COALESCE((SELECT SUM(x.amount_minor) FROM latest x WHERE x.kind='payment' AND x.status='active' AND x.invoice_id=i.event_key),0) p,COALESCE((SELECT SUM(x.amount_minor) FROM latest x WHERE x.kind='credit' AND x.status='active' AND x.invoice_id=i.event_key),0) c,COALESCE((SELECT SUM(x.amount_minor) FROM latest x WHERE x.kind='hold' AND x.status NOT IN ('release','void') AND x.invoice_id=i.event_key),0) h FROM inv i), calc AS (SELECT b.*,(SELECT t.discount_bps FROM latest t WHERE t.kind='terms' AND t.status='active' AND t.terms_code=b.terms_code AND t.business_date<=b.business_date ORDER BY t.business_date DESC LIMIT 1) dbps,(SELECT f.fx_num FROM latest f WHERE f.kind='fx' AND f.status='active' AND f.currency=b.currency AND f.business_date<=b.business_date ORDER BY f.business_date DESC LIMIT 1) fn,(SELECT f.fx_den FROM latest f WHERE f.kind='fx' AND f.status='active' AND f.currency=b.currency AND f.business_date<=b.business_date ORDER BY f.business_date DESC LIMIT 1) fd FROM bal b) SELECT SUM(CAST(ROUND(MAX(0,MAX(0,gross-p-c)-h)*CASE WHEN '2026-10-23'<=discount_until THEN (10000-dbps)/10000.0 ELSE 1.0 END*fn/fd,0) AS INTEGER)) usd_cents FROM calc WHERE fn IS NOT NULL AND fd IS NOT NULL\"}}"}}
